    [DataContract] public sealed class JevCalibrationBenchmarkReport { [DataMember(Order=1)] public string SchemaVersion {get;set;}=JevCalibrationPackageStore.SchemaVersion; [DataMember(Order=2)] public string CalibrationPackageId {get;set;}=string.Empty; [DataMember(Order=3)] public string CalibrationCasesSha256 {get;set;}=string.Empty; [DataMember(Order=4)] public string EngineerLabelsSha256 {get;set;}=string.Empty; [DataMember(Order=5)] public bool AdvisoryOnly {get;set;}=true; [DataMember(Order=6)] public bool ProductionThresholdSelected {get;set;} [DataMember(Order=7)] public string ThresholdStatus {get;set;}="NO_PRODUCTION_THRESHOLD_SELECTED"; [DataMember(Order=8)] public string? Model {get;set;} [DataMember(Order=9)] public DateTime BenchmarkTimestampUtc {get;set;} [DataMember(Order=10)] public int LabeledSampleCount {get;set;} [DataMember(Order=11)] public int ValidPredictionCount {get;set;} [DataMember(Order=12)] public int UnavailablePredictionCount {get;set;} [DataMember(Order=13)] public int InvalidPredictionCount {get;set;} [DataMember(Order=14)] public int ExactMatchCount {get;set;} [DataMember(Order=15)] public int IncorrectCount {get;set;} [DataMember(Order=16)] public int UnknownPredictionCount {get;set;} [DataMember(Order=17)] public double? Coverage {get;set;} [DataMember(Order=18)] public double? ExactMatchRate {get;set;} [DataMember(Order=19)] public double? ClassifiedAccuracy {get;set;} [DataMember(Order=20)] public List<JevCalibrationMatrixRow> ConfusionMatrix {get;set;}=new List<JevCalibrationMatrixRow>(); [DataMember(Order=21)] public List<JevCalibrationConfidenceBucket> ConfidenceBuckets {get;set;}=new List<JevCalibrationConfidenceBucket>(); [DataMember(Order=22)] public List<JevCalibrationThresholdObservation> ThresholdObservations {get;set;}=new List<JevCalibrationThresholdObservation>(); [DataMember(Order=23)] public List<JevCalibrationPerLabelSummary> PerLabelSummary {get;set;}=new List<JevCalibrationPerLabelSummary>(); [DataMember(Order=24)] public List<JevCalibrationSampleResult> SampleResults {get;set;}=new List<JevCalibrationSampleResult>(); }
    [DataContract] public sealed class JevCalibrationSampleResult {[DataMember(Order=1)]public string EvidenceId{get;set;}=string.Empty;[DataMember(Order=2)]public string InputProjectionSha256{get;set;}=string.Empty;[DataMember(Order=3)]public string EngineerLabel{get;set;}=string.Empty;[DataMember(Order=4,EmitDefaultValue=false)]public string? PredictedLabel{get;set;}[DataMember(Order=5)]public double? Confidence{get;set;}[DataMember(Order=6)]public bool? Correct{get;set;}[DataMember(Order=7)]public string AdvisoryStatus{get;set;}=string.Empty;[DataMember(Order=8,EmitDefaultValue=false)]public string? ErrorCategory{get;set;}}
    [DataContract] public sealed class JevCalibrationMatrixRow {[DataMember(Order=1)]public string EngineerLabel{get;set;}=string.Empty;[DataMember(Order=2)]public List<int> Counts{get;set;}=new List<int>();}
    [DataContract] public sealed class JevCalibrationConfidenceBucket {[DataMember(Order=1)]public string Range{get;set;}=string.Empty;[DataMember(Order=2)]public int SampleCount{get;set;}[DataMember(Order=3)]public int CorrectCount{get;set;}[DataMember(Order=4)]public int IncorrectCount{get;set;}[DataMember(Order=5)]public double? Accuracy{get;set;}}
    [DataContract] public sealed class JevCalibrationThresholdObservation {[DataMember(Order=1)]public double Threshold{get;set;}[DataMember(Order=2)]public int EligibleCount{get;set;}[DataMember(Order=3)]public double? Coverage{get;set;}[DataMember(Order=4)]public int CorrectEligibleCount{get;set;}[DataMember(Order=5)]public int IncorrectEligibleCount{get;set;}[DataMember(Order=6)]public double? EligibleAccuracy{get;set;}}
    [DataContract] public sealed class JevCalibrationPerLabelSummary {[DataMember(Order=1)]public string Label{get;set;}=string.Empty;[DataMember(Order=2)]public int Support{get;set;}[DataMember(Order=3)]public int PredictedCount{get;set;}[DataMember(Order=4)]public int CorrectCount{get;set;}}
    public static class JevCalibrationBenchmarkRunner
    {
        public static JevCalibrationBenchmarkReport Create(JevCalibrationPackage package,IReadOnlyList<JevEngineerLabel> labels,JevSemanticAdvisorySidecar results,string casesHash,string labelsHash)
        {
            Dictionary<string,JevSemanticAssistResult> byId=(results.Results??new List<JevSemanticAssistResult>()).ToDictionary(x=>x.EvidenceId,StringComparer.Ordinal); var report=new JevCalibrationBenchmarkReport{CalibrationPackageId=package.CalibrationPackageId,CalibrationCasesSha256=casesHash,EngineerLabelsSha256=labelsHash,BenchmarkTimestampUtc=DateTime.UtcNow};
            foreach(var label in labels.OrderBy(x=>x.EvidenceId,StringComparer.Ordinal)){byId.TryGetValue(label.EvidenceId,out JevSemanticAssistResult? r);string status=r?.AdvisoryStatus??JevSemanticAdvisoryStates.InvalidResponse;bool classified=status==JevSemanticAdvisoryStates.Classified;bool? correct=classified?(bool?)(r!.Choice==label.EngineerLabel):null;report.SampleResults.Add(new JevCalibrationSampleResult{EvidenceId=label.EvidenceId,InputProjectionSha256=label.InputProjectionSha256,EngineerLabel=label.EngineerLabel!,PredictedLabel=r?.Choice,Confidence=r?.Confidence,Correct=correct,AdvisoryStatus=status,ErrorCategory=r?.ErrorCategory});}
            report.LabeledSampleCount=report.SampleResults.Count; report.ValidPredictionCount=report.SampleResults.Count(x=>x.AdvisoryStatus==JevSemanticAdvisoryStates.Classified);report.UnavailablePredictionCount=report.SampleResults.Count(x=>x.AdvisoryStatus==JevSemanticAdvisoryStates.Unavailable);report.InvalidPredictionCount=report.SampleResults.Count(x=>x.AdvisoryStatus==JevSemanticAdvisoryStates.InvalidResponse);report.ExactMatchCount=report.SampleResults.Count(x=>x.Correct==true);report.IncorrectCount=report.SampleResults.Count(x=>x.AdvisoryStatus==JevSemanticAdvisoryStates.Classified&&x.Correct==false);report.UnknownPredictionCount=report.SampleResults.Count(x=>x.AdvisoryStatus==JevSemanticAdvisoryStates.Classified&&x.PredictedLabel==JevSemanticLabels.Unknown);report.Coverage=Rate(report.ValidPredictionCount,report.LabeledSampleCount);report.ExactMatchRate=Rate(report.ExactMatchCount,report.LabeledSampleCount);report.ClassifiedAccuracy=Rate(report.ExactMatchCount,report.ValidPredictionCount);
            string[] models=results.Results.Where(x=>x.AdvisoryStatus==JevSemanticAdvisoryStates.Classified&&!string.IsNullOrWhiteSpace(x.Model)).Select(x=>x.Model!).Distinct(StringComparer.Ordinal).ToArray();if(models.Length>1)throw new InvalidOperationException("BENCHMARK_MODEL_MISMATCH");report.Model=models.Length==1?models[0]:null;
            foreach(string label in JevSemanticLabels.All){var row=new JevCalibrationMatrixRow{EngineerLabel=label,Counts=JevSemanticLabels.All.Select(x=>0).ToList()};foreach(var s in report.SampleResults.Where(x=>x.EngineerLabel==label&&x.AdvisoryStatus==JevSemanticAdvisoryStates.Classified))row.Counts[Array.IndexOf(JevSemanticLabels.All,s.PredictedLabel!) ]++;report.ConfusionMatrix.Add(row);report.PerLabelSummary.Add(new JevCalibrationPerLabelSummary{Label=label,Support=report.SampleResults.Count(x=>x.EngineerLabel==label),PredictedCount=report.SampleResults.Count(x=>x.AdvisoryStatus==JevSemanticAdvisoryStates.Classified&&x.PredictedLabel==label),CorrectCount=report.SampleResults.Count(x=>x.Correct==true&&x.EngineerLabel==label)});}
            double[] lows={0,.5,.7,.8,.9,.95};double[] highs={.5,.7,.8,.9,.95,1};for(int i=0;i<6;i++){var x=report.SampleResults.Where(s=>s.AdvisoryStatus==JevSemanticAdvisoryStates.Classified&&s.Confidence>=lows[i]&&(i==5?s.Confidence<=highs[i]:s.Confidence<highs[i])).ToList();report.ConfidenceBuckets.Add(new JevCalibrationConfidenceBucket{Range="["+lows[i].ToString("0.00")+", "+highs[i].ToString("0.00")+(i==5?"]":")"),SampleCount=x.Count,CorrectCount=x.Count(s=>s.Correct==true),IncorrectCount=x.Count(s=>s.Correct==false),Accuracy=Rate(x.Count(s=>s.Correct==true),x.Count)});}foreach(double t in new[]{.5,.6,.7,.8,.9,.95}){var x=report.SampleResults.Where(s=>s.AdvisoryStatus==JevSemanticAdvisoryStates.Classified&&s.Confidence>=t).ToList();report.ThresholdObservations.Add(new JevCalibrationThresholdObservation{Threshold=t,EligibleCount=x.Count,Coverage=Rate(x.Count,report.LabeledSampleCount),CorrectEligibleCount=x.Count(s=>s.Correct==true),IncorrectEligibleCount=x.Count(s=>s.Correct==false),EligibleAccuracy=Rate(x.Count(s=>s.Correct==true),x.Count)});}return report;
        }
        private static double? Rate(int n,int d)=>d==0?(double?)null:(double)n/d;
    }
    public sealed class JevCalibrationReportCheck { public string Status {get;set;}=string.Empty; public JevCalibrationBenchmarkReport? Report {get;set;} }
    public static class JevCalibrationBenchmarkStore { public static string HashFile(string path){using(SHA256 h=SHA256.Create())using(FileStream s=File.OpenRead(path))return BitConverter.ToString(h.ComputeHash(s)).Replace("-",string.Empty);} public static JevCalibrationReportCheck Check(string directory,string packageId,string casesHash,string labelsHash){string p=Path.Combine(directory,"benchmark-report.json");if(!File.Exists(p))return new JevCalibrationReportCheck{Status="NO_EXISTING_REPORT"};using(FileStream s=File.OpenRead(p)){var x=(JevCalibrationBenchmarkReport)new DataContractJsonSerializer(typeof(JevCalibrationBenchmarkReport)).ReadObject(s)!;if(x.SchemaVersion!=JevCalibrationPackageStore.SchemaVersion||x.CalibrationPackageId!=packageId||x.CalibrationCasesSha256!=casesHash||x.EngineerLabelsSha256!=labelsHash)throw new InvalidOperationException("BENCHMARK_INPUT_CHANGED");return new JevCalibrationReportCheck{Status="EXISTING_REPORT_MATCH",Report=x};}} public static JevCalibrationBenchmarkReport ReadOrWrite(string directory,JevCalibrationBenchmarkReport report){JevCalibrationReportCheck existing=Check(directory,report.CalibrationPackageId,report.CalibrationCasesSha256,report.EngineerLabelsSha256);if(existing.Report!=null)return existing.Report;string p=Path.Combine(directory,"benchmark-report.json");using(FileStream s=new FileStream(p,FileMode.CreateNew,FileAccess.Write,FileShare.None))new DataContractJsonSerializer(typeof(JevCalibrationBenchmarkReport)).WriteObject(s,report);return report;} }
}
